<?php require __DIR__.'/config/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']); if($title!==''){ $s=$db->pdo()->prepare('INSERT INTO tasks(title,due_date) VALUES(?,?)'); $s->execute(array($title, $_POST['due_date']?:null)); }}
if(isset($_GET['done'])){$s=$db->pdo()->prepare("UPDATE tasks SET status='done' WHERE id=?");$s->execute(array((int)$_GET['done']));}
$rows=$db->pdo()->query('SELECT * FROM tasks ORDER BY status, due_date IS NULL, due_date, id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@3.4.1/dist/css/bootstrap.min.css"></head><body><div class="container"><p><a href="index.php">← Dashboard</a></p><h1>Tasks</h1><form method="post" class="form-inline"><input class="form-control" name="title" placeholder="Task" required><input class="form-control" type="date" name="due_date"><button class="btn btn-primary">Add</button></form><hr><table class="table"><tr><th>Task</th><th>Due</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='done'):?><a class="btn btn-xs btn-success" href="?done=<?=$r['id']?>">Done</a><?php endif;?></td></tr><?php endforeach;?></table></div></body></html>
